    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        cost = [[0] * 26 for _ in range(26)]
        for a in range(26):
            forward = [0] * 26
            backward = [0] * 26
            run = 0
            for step in range(1, 26):
                run += nextCost[(a + step - 1) % 26]
                forward[(a + step) % 26] = run
            run = 0
