                run += previousCost[(a - step + 1) % 26]
                backward[(a - step) % 26] = run
            for b in range(26):
                cost[a][b] = min(forward[b], backward[b])
        total = 0
        for x, y in zip(s, t):
            total += cost[ord(x) - 97][ord(y) - 97]
        return total

